```tsx
import "./TimeList.css";

export type TimeState = "past" | "next" | "later";

export interface TimeItem {
  name: string;
  time: string;
  state: TimeState;
}

export interface TimeListProps {
  items: readonly TimeItem[];
  label?: string;
  onSelect?: (item: TimeItem, index: number) => void;
}

const STATE_TEXT: Record<TimeState, string> = {
  past: "passed",
  next: "next",
  later: "later",
};

export function TimeList({
  items,
  label = "Times through the day",
  onSelect,
}: TimeListProps) {
  return (
    <ol className="time-list" aria-label={label}>
      {items.map((item, index) => (
        <li
          key={`${item.name}-${item.time}-${index}`}
          className="time-list__item"
          data-state={item.state}
          aria-current={item.state === "next" ? "time" : undefined}
        >
          <button
            type="button"
            className="time-list__row"
            onClick={() => onSelect?.(item, index)}
          >
            <span className="time-list__name">{item.name}</span>
            {item.state === "next" && (
              <span className="time-list__badge" aria-hidden="true">
                Next
              </span>
            )}
            <time className="time-list__time">{item.time}</time>
            <span className="sr-only">, {STATE_TEXT[item.state]}</span>
          </button>
        </li>
      ))}
    </ol>
  );
}
```

