.time-list {
  list-style: none;
  margin: 0;
  padding: 0;
  color: var(--ink);
  font: inherit;
}

.time-list__item {
  border-bottom: 1px solid var(--hair);
}

.time-list__item:last-child {
  border-bottom: 0;
}

.time-list__row {
  display: flex;
  align-items: center;
  gap: 0.75em;
  width: 100%;
  margin: 0;
  padding: 0.7em 0.9em;
  border: 0;
  border-radius: 0.5em;
  background: none;
  color: inherit;
  font: inherit;
  font-size: clamp(0.95rem, 1.2vw + 0.6rem, 1.35rem);
  text-align: start;
  cursor: pointer;
  transition: background-color 180ms ease, color 180ms ease;
}

.time-list__row:hover {
  background: var(--myelin-wash);
}

.time-list__name {
  flex: 1 1 auto;
  min-width: 0;
}

.time-list__time {
  flex: 0 0 auto;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* Past: quieter text, no fill. Colour comes from the muted token, not opacity. */
.time-list__item[data-state="past"] .time-list__row {
  color: var(--muted);
}

/* Next: the one highlighted row. */
.time-list__item[data-state="next"] .time-list__row {
  background: var(--myelin-wash);
  font-weight: 600;
}

.time-list__item[data-state="next"] .time-list__row:hover {
  background: var(--myelin-wash);
}

.time-list__badge {
  flex: 0 0 auto;
  padding: 0.2em 0.7em;
  border-radius: 999px;
  background: var(--myelin);
  color: var(--slide);
  font-size: 0.7em;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

:root[data-motion="reduce"] .time-list__row,
:root[data-motion="reduce"] .time-list__row:hover {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .time-list__row {
    transition: none;
  }
}
